// MSG91 delivery for the Supabase Auth Send SMS hook.
// The OTP is generated by Supabase. This module only forwards it.

export interface SmsHookEnv {
  secret: string;
  authKey: string;
  templateId: string;
  senderId: string;
}

export interface SmsHookBody {
  user?: { phone?: string; new_phone?: string };
  sms?: { otp?: string; phone?: string };
}

export interface HookResult {
  status: number;
  body: { error?: { http_code: number; message: string } };
}

const OTP_URL = "https://control.msg91.com/api/v5/otp";

/** Strips a 6-digit code and an auth key so a failure cannot echo them. */
export function redactSecrets(text: string): string {
  return text
    .replace(/\b\d{4,8}\b/g, "")
    .replace(/authkey[=:\s]+\S+/gi, "authkey")
    .replace(/\s{2,}/g, " ")
    .trim()
    .slice(0, 180);
}

export function hookError(httpCode: number, message: string): Response {
  const code = httpCode >= 400 && httpCode <= 599 ? httpCode : 500;
  const safe = redactSecrets(message) || "The SMS was not sent.";
  return new Response(
    JSON.stringify({ error: { http_code: code, message: safe } }),
    { status: code, headers: { "Content-Type": "application/json" } },
  );
}

export function hookOk(): Response {
  return new Response("{}", {
    status: 200,
    headers: { "Content-Type": "application/json" },
  });
}

/** Standard Webhooks secret: `v1,whsec_<base64>`. */
export function webhookSecretBytes(secret: string): Uint8Array | null {
  const trimmed = secret.trim().replace(/^v1,/, "").replace(/^whsec_/, "");
  if (!trimmed) {
    return null;
  }
  try {
    const binary = atob(trimmed);
    return Uint8Array.from(binary, (char) => char.charCodeAt(0));
  } catch {
    return null;
  }
}

function timingSafeEqual(left: string, right: string): boolean {
  if (left.length === 0 || left.length !== right.length) {
    return false;
  }
  let diff = 0;
  for (let i = 0; i < left.length; i++) {
    diff |= left.charCodeAt(i) ^ right.charCodeAt(i);
  }
  return diff === 0;
}

export async function signWebhook(
  secretBytes: Uint8Array,
  id: string,
  timestamp: string,
  rawBody: string,
): Promise<string> {
  const keyBytes = secretBytes.buffer.slice(
    secretBytes.byteOffset,
    secretBytes.byteOffset + secretBytes.byteLength,
  ) as ArrayBuffer;
  const key = await crypto.subtle.importKey(
    "raw",
    keyBytes,
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"],
  );
  const signed = `${id}.${timestamp}.${rawBody}`;
  const mac = await crypto.subtle.sign(
    "HMAC",
    key,
    new TextEncoder().encode(signed),
  );
  const bytes = new Uint8Array(mac);
  let binary = "";
  for (const byte of bytes) {
    binary += String.fromCharCode(byte);
  }
  return btoa(binary);
}

export async function verifyStandardWebhook(
  rawBody: string,
  headers: Headers,
  secret: string,
  nowMs = Date.now(),
): Promise<{ ok: true } | { ok: false; message: string }> {
  const id = headers.get("webhook-id") ?? "";
  const timestamp = headers.get("webhook-timestamp") ?? "";
  const signatureHeader = headers.get("webhook-signature") ?? "";
  if (!id || !timestamp || !signatureHeader) {
    return { ok: false, message: "Missing webhook signature." };
  }
  const ts = Number(timestamp);
  if (!Number.isFinite(ts)) {
    return { ok: false, message: "Invalid webhook timestamp." };
  }
  if (Math.abs(nowMs / 1000 - ts) > 5 * 60) {
    return { ok: false, message: "Webhook timestamp is outside the allowed window." };
  }
  const keyBytes = webhookSecretBytes(secret);
  if (!keyBytes) {
    return { ok: false, message: "SMS hook secret is not configured." };
  }
  const expected = await signWebhook(keyBytes, id, timestamp, rawBody);
  const match = signatureHeader.split(" ").some((part) => {
    const value = part.trim().startsWith("v1,") ? part.trim().slice(3) : part.trim();
    return timingSafeEqual(value, expected);
  });
  if (!match) {
    return { ok: false, message: "Webhook signature was not accepted." };
  }
  return { ok: true };
}

/** The number Auth generated the OTP for. Phone change uses sms.phone. */
export function destinationPhone(body: SmsHookBody): string | null {
  const smsPhone = body.sms?.phone?.trim();
  if (smsPhone) {
    return smsPhone;
  }
  const next = body.user?.new_phone?.trim();
  if (next) {
    return next;
  }
  const current = body.user?.phone?.trim();
  return current || null;
}

/** MSG91 wants digits with the country code and no plus. */
export function msg91Mobile(phone: string): string | null {
  const digits = phone.replace(/\D/g, "");
  if (!/^91[6-9]\d{9}$/.test(digits)) {
    return null;
  }
  return digits;
}

export function buildMsg91Request(input: {
  authKey: string;
  templateId: string;
  senderId: string;
  mobile: string;
  otp: string;
}): { url: string; init: RequestInit } {
  const url = new URL(OTP_URL);
  url.searchParams.set("template_id", input.templateId);
  url.searchParams.set("mobile", input.mobile);
  url.searchParams.set("otp", input.otp);
  url.searchParams.set("otp_expiry", "5");
  url.searchParams.set("sender", input.senderId);
  return {
    url: url.toString(),
    init: {
      method: "POST",
      headers: {
        authkey: input.authKey,
        accept: "application/json",
        "content-type": "application/json",
      },
      body: "{}",
    },
  };
}

export async function handleSendSms(input: {
  rawBody: string;
  headers: Headers;
  env: SmsHookEnv;
  fetchImpl: typeof fetch;
  nowMs?: number;
}): Promise<Response> {
  const { env } = input;
  if (!env.secret || !env.authKey || !env.templateId || !env.senderId) {
    return hookError(500, "SMS provider is not configured.");
  }
  const verified = await verifyStandardWebhook(
    input.rawBody,
    input.headers,
    env.secret,
    input.nowMs,
  );
  if (!verified.ok) {
    return hookError(401, verified.message);
  }
  let body: SmsHookBody;
  try {
    body = JSON.parse(input.rawBody) as SmsHookBody;
  } catch {
    return hookError(400, "The SMS hook payload was not readable.");
  }
  const otp = body.sms?.otp?.trim() ?? "";
  if (!/^\d{6}$/.test(otp)) {
    return hookError(400, "Supabase did not include a 6-digit code.");
  }
  const phone = destinationPhone(body);
  const mobile = phone ? msg91Mobile(phone) : null;
  if (!mobile) {
    return hookError(400, "The SMS hook did not include an Indian mobile number.");
  }
  const request = buildMsg91Request({
    authKey: env.authKey,
    templateId: env.templateId,
    senderId: env.senderId,
    mobile,
    otp,
  });
  let response: Response;
  try {
    response = await input.fetchImpl(request.url, request.init);
  } catch {
    return hookError(502, "MSG91 could not be reached.");
  }
  const text = await response.text();
  if (!response.ok || /"type"\s*:\s*"error"/i.test(text)) {
    return hookError(response.ok ? 502 : response.status, redactSecrets(text) || "MSG91 did not send the SMS.");
  }
  if (text.includes(otp)) {
    return hookOk();
  }
  return hookOk();
}
